// Daily bank sync and categorisation for Actual Budget, through the loopback
// actual-bridge (hosts/nixos/inari/services/actual/bridge.cjs).
//
// The owner's own history decides; whatever it cannot decide goes to the
// alert spine instead of being guessed.
//
// The local classifier path is off. Measured on 2026-11-03 against the 20
// categorised bookings of the live budget, hiding each payee's other rows:
// qwen3.5-9b got 3 right, 8 wrong and abstained on 9, and called itself sure
// on every wrong one (dm -> Lebensmittel, Allianz pension -> Urlaub). The
// categories are personal (pocket money, a pension, split gym purchases), so
// a payee name does not carry them. Set ACTUAL_USE_MODEL=true only after a
// new measurement beats that; its answers carry #auto in the notes.
const SOURCE = 'actual-budget';
const BRIDGE = $env.ACTUAL_BRIDGE_URL;
const KEY = $env.ACTUAL_BRIDGE_API_KEY;
const BUDGET_URL = $env.ACTUAL_URL;
const CANDIDATE_DAYS = 45;
const HISTORY_DAYS = 365;
const MAX_MODEL_CALLS = 15;
const EXAMPLES = 30;
const AUTO_TAG = '#auto';
const UNKNOWN = 'unbekannt';

const http = this.helpers.httpRequest.bind(this.helpers);
const bridge = (route, body = {}) => http({
  method: 'POST', url: `${BRIDGE}${route}`, headers: {Authorization: `Bearer ${KEY}`},
  body, json: true, timeout: 10 * 60 * 1000,
});
const alert = (payload) => http({
  method: 'POST', url: $env.ALERT_WEBHOOK_URL, body: {source: SOURCE, ...payload}, json: true, timeout: 30000,
});
const message = (error) => String(error?.response?.body?.error ?? error?.message ?? error).slice(0, 300);

// {{{ Bridge reachable at all
let sync;
try {
  sync = await bridge('/bank-sync');
} catch (error) {
  await alert({
    fingerprint: `${SOURCE}:bridge`, severity: 'warning',
    title: 'Actual: Bank-Sync nicht möglich',
    message: `Die Actual-Bridge hat nicht geantwortet: ${message(error)}\n\nLäuft actual-bridge.service, und gibt es die Session der Bridge noch?`,
  });
  return [{json: {ok: false, stage: 'bank-sync', error: message(error)}}];
}
await alert({fingerprint: `${SOURCE}:bridge`, resolved: true, title: 'Actual: Bank-Sync nicht möglich'});
// }}}
// {{{ Per-account bank sync results
// Accounts without a bank link answer with an error too; those are not
// failures, so only linked-account errors reach the owner.
const notLinked = (result) => /not linked|no.*(bank|sync).*account|account.*not.*sync|ACCOUNT_NOT_LINKED|invalid-account/i.test(`${result.code} ${result.error}`);
const failed = [];
for (const result of sync.accounts) {
  const title = `Actual: Bank-Sync für ${result.name} fehlgeschlagen`;
  if (result.ok || notLinked(result)) {
    await alert({fingerprint: `${SOURCE}:bank:${result.id}`, resolved: true, title});
    continue;
  }
  failed.push(result);
  await alert({
    fingerprint: `${SOURCE}:bank:${result.id}`, severity: 'warning', title, url: BUDGET_URL,
    message: `${result.error}\n\nMeist ist die Bankfreigabe abgelaufen: in Actual unter Bank-Sync das Konto neu verknüpfen.`,
  });
}
// }}}
// {{{ Snapshot
const snap = await bridge('/snapshot', {days: HISTORY_DAYS});
const accounts = new Map(snap.accounts.map((account) => [account.id, account]));
const payees = new Map(snap.payees.map((payee) => [payee.id, payee]));
const categories = snap.categories.filter((category) => !category.hidden);
const categoryById = new Map(snap.categories.map((category) => [category.id, category]));
const since = new Date(Date.now() - CANDIDATE_DAYS * 86400000).toISOString().slice(0, 10);

const budgetRow = (tx) => !tx.transfer && !tx.starting_balance && accounts.get(tx.account) && !accounts.get(tx.account).offbudget
  && !payees.get(tx.payee)?.transfer;
const history = snap.transactions.filter((tx) => budgetRow(tx) && tx.category && categoryById.has(tx.category));
const candidates = snap.transactions.filter((tx) => budgetRow(tx) && !tx.category && tx.date >= since);
// }}}
// {{{ Matching on the owner's own history
const STOP = new Set(['gmbh', 'ag', 'kg', 'co', 'se', 'ug', 'mbh', 'ev', 'sagt', 'danke', 'sepa', 'lastschrift',
  'kartenzahlung', 'debitk', 'visa', 'girocard', 'gutschrift', 'ueberweisung', 'uberweisung', 'dauerauftrag',
  'elv', 'pos', 'nr', 'de', 'www', 'com', 'online', 'gmbhco', 'fil', 'filiale']);
const INTERMEDIARIES = new Set(['paypal', 'klarna', 'sumup', 'stripe', 'adyen', 'zettle', 'payone',
  'unzer', 'mollie', 'google', 'apple', 'amazon', 'sofort', 'giropay', 'wero', 'vr', 'sparkasse']);
function normalise(text) {
  const words = String(text ?? '').toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
    .replace(/[0-9]{3,}/g, ' ').replace(/[^a-z0-9]+/g, ' ')
    .split(' ').filter((word) => word.length > 1 && !STOP.has(word));
  // The first word names the merchant (REWE Markt GmbH, REWE 4711): branch
  // numbers and towns differ between bookings. Payment providers name nobody,
  // so they never match by name and go to the model with their full text.
  return words.length && !INTERMEDIARIES.has(words[0]) ? words[0] : '';
}
const payeeName = (tx) => payees.get(tx.payee)?.name ?? tx.imported_payee ?? '';
const sign = (tx) => Math.sign(tx.amount);

// Two earlier bookings in the same category, or a three-quarter majority of
// four or more. One example was not enough: measured leave-one-out on the
// live budget it filed a gym purchase by the one booking left of a payee
// that has two categories.
function vote(rows) {
  const counts = new Map();
  for (const row of rows) counts.set(row.category, (counts.get(row.category) ?? 0) + 1);
  const ranked = [...counts.entries()].sort((a, b) => b[1] - a[1]);
  if (!ranked.length) return null;
  const [category, top] = ranked[0];
  const share = top / rows.length;
  return (rows.length >= 2 && share === 1) || (rows.length >= 4 && share >= 0.75) ? category : null;
}
function fromHistory(tx) {
  const sameSign = history.filter((row) => sign(row) === sign(tx));
  if (tx.payee) {
    const byPayee = vote(sameSign.filter((row) => row.payee === tx.payee));
    if (byPayee) return byPayee;
  }
  const key = normalise(payeeName(tx)) || normalise(tx.imported_payee);
  if (!key) return null;
  return vote(sameSign.filter((row) => (normalise(payeeName(row)) || normalise(row.imported_payee)) === key));
}
// }}}
// {{{ Classifier
const label = (category) => `${category.group} / ${category.name}`;
function allowed(tx) {
  // Expenses never go to income categories; money coming in may be income or
  // a refund against an expense category.
  return categories.filter((category) => tx.amount > 0 || !category.is_income);
}
function examples(tx) {
  const seen = new Set();
  const rows = [];
  for (const row of [...history].reverse()) {
    if (sign(row) !== sign(tx)) continue;
    const name = payeeName(row);
    const key = normalise(name);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    rows.push(`${name} -> ${label(categoryById.get(row.category))}`);
    if (rows.length >= EXAMPLES) break;
  }
  return rows;
}
async function fromModel(tx) {
  const options = allowed(tx);
  const labels = options.map(label);
  const prompt = [
    'Du ordnest eine Banktransaktion einer Budgetkategorie zu.',
    'Antworte nur mit einer Kategorie aus der Liste. Wenn Empfänger und Verwendungszweck nicht eindeutig sind,',
    `antworte "${UNKNOWN}". Rate nicht: eine falsche Kategorie ist schlimmer als keine.`,
    'Setze "sicher" nur auf true, wenn die Zuordnung offensichtlich ist.',
    '',
    'Bisherige Zuordnungen des Nutzers:',
    ...examples(tx),
  ].join('\n');
  const input = {
    empfaenger: payeeName(tx), bank_empfaenger: tx.imported_payee, verwendungszweck: (tx.notes ?? '').slice(0, 300),
    betrag_eur: tx.amount / 100, konto: accounts.get(tx.account)?.name,
  };
  const response = await http({
    method: 'POST', url: $env.CLASSIFIER_URL, json: true, timeout: 5 * 60 * 1000,
    body: {
      stream: false, temperature: 0, max_tokens: 80,
      response_format: {type: 'json_schema', json_schema: {name: 'verdict', strict: true, schema: {
        type: 'object', additionalProperties: false, required: ['kategorie', 'sicher'],
        properties: {kategorie: {type: 'string', enum: [...labels, UNKNOWN]}, sicher: {type: 'boolean'}},
      }}},
      messages: [{role: 'system', content: prompt}, {role: 'user', content: JSON.stringify(input)}],
    },
  });
  const verdict = JSON.parse(response.choices[0].message.content);
  if (verdict.sicher !== true || verdict.kategorie === UNKNOWN) return null;
  const index = labels.indexOf(verdict.kategorie);
  return index === -1 ? null : options[index].id;
}
// }}}
// {{{ Decide
const updates = [];
const unresolved = [];
let modelCalls = 0;
let modelErrors = 0;
for (const tx of candidates) {
  const known = fromHistory(tx);
  if (known) {
    updates.push({id: tx.id, category: known, source: 'history'});
    continue;
  }
  if ($env.ACTUAL_USE_MODEL === 'true' && $env.CLASSIFIER_URL && modelCalls < MAX_MODEL_CALLS) {
    modelCalls += 1;
    try {
      const guess = await fromModel(tx);
      if (guess) {
        updates.push({id: tx.id, category: guess, note: AUTO_TAG, source: 'model'});
        continue;
      }
    } catch (error) {
      // A model that is down must not lose the transaction: it is reported
      // as unresolved below and retried on the next run.
      modelErrors += 1;
    }
  }
  unresolved.push(tx);
}
const applied = updates.length
  ? await bridge('/categorize', {updates: updates.map(({id, category, note}) => ({id, category, note}))})
  : {applied: [], skipped: []};
// }}}
// {{{ Report
const money = (cents) => (cents / 100).toLocaleString('de-DE', {style: 'currency', currency: 'EUR'});
const day = (date) => `${date.slice(8, 10)}.${date.slice(5, 7)}.`;
const fingerprint = `${SOURCE}:uncategorized`;
if (unresolved.length) {
  const lines = unresolved.slice(0, 10).map((tx) => `${day(tx.date)} ${money(tx.amount)} ${payeeName(tx) || '?'} (${accounts.get(tx.account)?.name})`);
  if (unresolved.length > 10) lines.push(`… und ${unresolved.length - 10} weitere`);
  const auto = applied.applied.length ? `\n\n${applied.applied.length} andere wurden automatisch zugeordnet.` : '';
  const down = modelErrors ? `\n\nDas Klassifizierungsmodell war ${modelErrors}× nicht erreichbar.` : '';
  await alert({
    fingerprint, severity: 'info', url: BUDGET_URL,
    title: `Actual: ${unresolved.length} Buchung${unresolved.length === 1 ? '' : 'en'} ohne Kategorie`,
    message: `Dafür reichen die Daten nicht für eine sichere Zuordnung:\n\n${lines.join('\n')}${auto}${down}`,
  });
} else {
  await alert({fingerprint, resolved: true, title: 'Actual: Buchungen ohne Kategorie'});
}
return [{json: {
  ok: true,
  bankSyncFailed: failed.map(({name, error}) => ({name, error})),
  candidates: candidates.length,
  fromHistory: updates.filter((update) => update.source === 'history').length,
  fromModel: updates.filter((update) => update.source === 'model').length,
  applied: applied.applied.length,
  skipped: applied.skipped,
  unresolved: unresolved.length,
  modelCalls,
  modelErrors,
}}];
// }}}
